import{createJobBundle,validateJobBundle,verifyImportedResult,transitionBundleState}from"./bundles.js";
const $=id=>document.getElementById(id);let currentBundle=null,bundleState="cancelled",videoURL=null,selectedJobFile=null,lastBasePrompt="";
const provider=$("provider");if(provider&&!Array.from(provider.options).some(o=>o.value==="gpu-bundle")){const o=document.createElement("option");o.value="gpu-bundle";o.textContent="GPU worker (file bundle)";provider.append(o)}
const panel=document.createElement("section");panel.className="story";panel.id="gpu-bundle-panel";panel.innerHTML=`<b>GPU worker · file bundle</b><p>Inference runs on a GPU worker you control. <strong>UNVERIFIED ON REAL HARDWARE</strong> until a verification report is reviewed.</p><div class="grid2"><div><label for="gpu-engine">AI engine</label><select id="gpu-engine"><option value="ltx-video">LTX-Video (primary; license restrictions apply)</option><option value="wan2.2-ti2v-5b">Wan 2.2 TI2V-5B (fallback; higher memory requirements)</option></select></div><div><label for="gpu-continuity">Scene continuity</label><select id="gpu-continuity"><option value="last_frame">Last frame (default)</option><option value="none">No conditioning between scenes</option></select></div></div><div><label for="gpu-scenes">Editable per-scene prompts</label><div id="gpu-scene-prompts"></div><p class="hint">Default prompts are created locally. No paid language model is used.</p></div><button type="button" id="gpu-create" class="primary">Create job bundle</button><p id="gpu-bundle-state" role="status">Configure a job and create job.json.</p><div id="gpu-instructions" class="hidden"><h3>Run the GPU worker</h3><ol><li>Open <a href="./docs/WORKER-VERIFY.md" rel="noopener noreferrer">GPU worker verification instructions</a> and the <a href="./docs/BUNDLE-FORMAT.md" rel="noopener noreferrer">bundle format</a>.</li><li>Run the worker in a GPU notebook or a local NVIDIA GPU environment. No tunnel or inbound network is required.</li><li>Return with <code>result.mp4</code> and <code>manifest.json</code>.</li></ol><p><strong>Privacy:</strong> This file contains your prompt and image. It leaves your device only if you upload it to a notebook service or machine you choose.</p><label for="gpu-job-file">Optional previous job.json (for importing a result from history)</label><input id="gpu-job-file" type="file" accept="application/json,.json"><label for="gpu-import-files">Import result.mp4 and manifest.json together</label><input id="gpu-import-files" type="file" accept="video/mp4,application/json,.mp4,.json" multiple><button type="button" id="gpu-import" class="primary">Import result</button></div>`;
const form=$("form");form.insertBefore(panel,$("submit"));
function setState(next,msg){if(next!==bundleState&&!transitionBundleState(bundleState,next)&&!(bundleState==="cancelled"&&next==="awaiting_worker"))return;bundleState=next;if(provider.value==="gpu-bundle")$("cancel").disabled=next!=="awaiting_worker";$ ("gpu-bundle-state").textContent=msg;const labels={awaiting_worker:"Awaiting worker result",importing:"Importing and verifying",completed:"Completed",failed:"Failed",cancelled:"Cancelled — pending bundle discarded"};$("appstate").textContent=labels[next]||next;$("jobstate").textContent=labels[next]||next;$("detail").textContent=msg}
function defaultScenePrompt(base){return `${base} — continues the same scene with consistent subject, setting, lighting, and camera motion.`}
function buildSceneEditors(){const host=$("gpu-scene-prompts");if(!host)return;const old=new Map(Array.from(host.querySelectorAll("textarea"),ta=>[ta.dataset.scene,ta.value]));const count=Math.ceil(+$ ("duration").value/5),base=$("prompt").value.trim(),oldDefault=defaultScenePrompt(lastBasePrompt);host.replaceChildren();for(let i=0;i<count;i++){const lab=document.createElement("label");lab.textContent=`Scene ${i+1} prompt`;const ta=document.createElement("textarea");ta.rows=2;ta.maxLength=4000;ta.dataset.scene=String(i);const previous=old.get(String(i));ta.value=previous&&previous!==oldDefault?previous:defaultScenePrompt(base);lab.htmlFor=`gpu-scene-${i+1}`;ta.id=lab.htmlFor;host.append(lab,ta)}lastBasePrompt=base}
function toggle(){const on=provider.value==="gpu-bundle";panel.classList.toggle("hidden",!on);if(on){$("cancel").disabled=true;$("recipient").textContent="No request is sent from this browser. A job.json file is created for manual transfer.";$("disclosure").textContent="This file contains your prompt and image. It leaves your device only if you upload it to a notebook service or machine you choose.";$("negative").disabled=false;$("negativehelp").textContent="Included in the bundle; actual model behavior is engine-dependent.";$("tabimage").disabled=false;$("submit").classList.add("hidden");$("gpu-create").disabled=false;buildSceneEditors();if(bundleState==="cancelled")setState("cancelled","Choose Create job bundle. No AI runs in this browser.")}else{$("submit").classList.remove("hidden");$("cancel").disabled=true;}}
provider.addEventListener("change",toggle);$("duration").addEventListener("change",()=>{if(provider.value==="gpu-bundle")buildSceneEditors()});$("prompt").addEventListener("input",()=>{if(provider.value==="gpu-bundle")buildSceneEditors()});
$("gpu-create").addEventListener("click",async()=>{try{$("error").textContent="";const imageVisible=!$("imagefield").classList.contains("hidden"),imageFile=imageVisible?$("image").files[0]:null;if(imageVisible&&!imageFile)throw new Error("Choose a starting image or switch to Text to Video.");const scenePrompts=Array.from($("gpu-scene-prompts").querySelectorAll("textarea"),x=>x.value);const seed=$ ("seed").value===""?Math.floor(Math.random()*2147483647):Number($ ("seed").value);selectedJobFile=null;$("gpu-job-file").value="";currentBundle=await createJobBundle({prompt:$ ("prompt").value,negativePrompt:$ ("negative").value,aspect:$ ("ratio").value,totalSeconds:Number($ ("duration").value),seed,image:imageFile,engine:$ ("gpu-engine").value,continuity:$ ("gpu-continuity").value,scenePrompts});await validateJobBundle(currentBundle);const blob=new Blob([JSON.stringify(currentBundle,null,2)+"\n"],{type:"application/json"});const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="job.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$("gpu-instructions").classList.remove("hidden");setState("awaiting_worker",`Bundle ${currentBundle.jobId} created. Run it on a GPU worker, then import result.mp4 and manifest.json.`);$("progresslabel").textContent="Awaiting worker result";$ ("progress").value=0;$ ("pct").textContent="0%";}catch(e){setState("failed",e.message);$("error").textContent=e.message}});
$("gpu-job-file").addEventListener("change",async()=>{selectedJobFile=null;const f=$("gpu-job-file").files[0];if(!f)return;try{if(f.size>15*1024*1024)throw new Error("job.json exceeds the 15 MiB import limit.");const obj=JSON.parse(await f.text());await validateJobBundle(obj);selectedJobFile=obj;$("gpu-bundle-state").textContent=`Selected previous bundle ${obj.jobId}.`; }catch(e){$("error").textContent=e.message}});
$("gpu-import").addEventListener("click",async()=>{try{setState("importing","Checking the bundle ID, manifest schema, MP4 signature and SHA-256.");const files=Array.from($("gpu-import-files").files||[]);const video=files.find(f=>f.name.toLowerCase()==="result.mp4"||f.type==="video/mp4"||f.name.toLowerCase().endsWith(".mp4"));const mf=files.find(f=>f!==video&&f.name.toLowerCase()==="manifest.json")||files.find(f=>f!==video&&f.name.toLowerCase().endsWith(".json"));if(!video||!mf)throw new Error("Select result.mp4 and manifest.json together.");if(mf.size>5*1024*1024)throw new Error("manifest.json exceeds the 5 MiB limit.");const manifest=JSON.parse(await mf.text());const job=selectedJobFile||currentBundle;if(!job)throw new Error("Create a bundle in this session or select a previous job.json first.");const verified=await verifyImportedResult(video,manifest,job);if(videoURL)URL.revokeObjectURL(videoURL);videoURL=URL.createObjectURL(video);const v=document.createElement("video");v.controls=true;v.playsInline=true;v.preload="metadata";v.src=videoURL;await new Promise((resolve,reject)=>{v.onloadedmetadata=resolve;v.onerror=()=>reject(new Error("Imported MP4 could not be decoded by this browser."));setTimeout(()=>reject(new Error("Timed out while checking MP4 playback metadata.")),15000)});const label=document.createElement("b");if(verified.kind==="test_pattern")label.textContent="TEST PATTERN: not AI generated";else label.textContent=`Generated by ${verified.model} on ${verified.gpu} (self-reported by the worker; not independently verified)`;const result=$("result");result.replaceChildren(label,v);const download=$("download");download.href=videoURL;download.download="result.mp4";download.classList.remove("hidden");const entry={id:job.jobId,kind:verified.kind,createdAt:new Date().toISOString(),prompt:job.prompt,provider:"GPU worker (file bundle)",engine:manifest.engine.id,model:verified.model,status:"Completed"};const historyItem=document.createElement("li");historyItem.textContent=`${new Date(entry.createdAt).toLocaleString()} — ${verified.kind==="test_pattern"?"TEST PATTERN: not AI generated":"Imported worker result (model/GPU self-reported)"} — Completed — ${(job.prompt||"").slice(0,90)}`;if($("history").querySelector("li")?.textContent==="No completed jobs yet.")$("history").replaceChildren();$("history").prepend(historyItem);try{const key="syj-video-forge.history.v1",history=JSON.parse(localStorage.getItem(key)||"[]");history.unshift(entry);localStorage.setItem(key,JSON.stringify(history.slice(0,50)))}catch{}setState("completed",`Imported ${video.name}; SHA-256 verified. Worker hardware/model fields are self-reported.`);$("progresslabel").textContent="Import verified";$ ("progress").value=100;$ ("pct").textContent="100%"; }catch(e){setState("failed",e.message);$("error").textContent=e.message}});
$("cancel").addEventListener("click",()=>{currentBundle=null;selectedJobFile=null;$("gpu-instructions").classList.add("hidden");$("gpu-import-files").value="";$("gpu-job-file").value="";setState("cancelled","Pending bundle discarded. No GPU job was cancelled remotely.")});
// Capture submit before the existing mock/local provider handler; other providers are untouched.
form.addEventListener("submit",e=>{if(provider.value!=="gpu-bundle")return;e.preventDefault();e.stopImmediatePropagation();$("gpu-create").click()},true);
toggle();

$("check").addEventListener("click",e=>{if(provider.value!=="gpu-bundle")return;e.preventDefault();e.stopImmediatePropagation();$("backend").textContent="GPU worker uses manual file bundles; no backend connection is needed.";},true);
